import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { createAnnouncementHandler } from "../handlers/createAnnouncementHandler";
import type { ApiError } from "../runtime/client";
import type { CreateSubTeamAnnouncementRequest } from "../types/CreateSubTeamAnnouncementRequest";
import type { TeamPartition } from "../types/TeamPartition";

type Data = Awaited<ReturnType<typeof createAnnouncementHandler>>;
type Vars = { teamPk: TeamPartition; body: CreateSubTeamAnnouncementRequest };

export function useCreateAnnouncement(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => createAnnouncementHandler(vars.teamPk, vars.body),
    ...options,
  });
}
